-- Tell whether a character can see another tile without a wall blocking the view.
-- line-of-sight: original MIT-licensed native educational port.
-- Generated by tools/ports/generate.py; edit the specification to preserve parity.
-- Input: [width,height,start_x,start_y,goal_x,goal_y,...grid]
-- Output: [visible_flag]
-- Integer tile centers; zero is transparent. Corner ties test both side cells to prevent diagonal
-- wall leaks.
-- Precondition: finite, correctly shaped data; integer indices/counts/IDs.
-- See ../PORTS.md for examples, limits, and the shared test fixtures.

-- Count how many numbers are in this list.
local function port_length(a) return #a end
-- Read one number at a zero-based position; stop if that position does not exist.
local function port_get(a,i) assert(i>=0 and i==math.floor(i) and i<#a,"index"); return a[i+1] end
-- Remove a negative sign so a distance or size is not negative.
local function port_abs_num(a) return math.abs(a) end

-- 1. Walk a straight line from the starting tile center to the target tile center.
-- 2. Check every tile touched by the line.
-- 3. When the line crosses a corner, check both side tiles too.
-- 4. Any wall blocks sight. This prevents seeing through two walls that meet diagonally.
local function compute(data)
    local w = 0
    local h = 0
    local x = 0
    local y = 0
    local gx = 0
    local gy = 0
    local nx = 0
    local ny = 0
    local sx = 0
    local sy = 0
    local ix = 0
    local iy = 0
    local decision = 0
    w = port_get(data, 0)
    h = port_get(data, 1)
    x = port_get(data, 2)
    y = port_get(data, 3)
    gx = port_get(data, 4)
    gy = port_get(data, 5)
    if ((w < 1) or (h < 1) or (port_length(data) ~= (6 + (w * h)))) then
        return {-(1)}
    end
    if ((x < 0) or (y < 0) or (gx < 0) or (gy < 0) or (x >= w) or (gx >= w) or (y >= h) or (gy >= h)) then
        return {0}
    end
    if ((port_get(data, ((6 + (y * w)) + x)) ~= 0) or (port_get(data, ((6 + (gy * w)) + gx)) ~= 0)) then
        return {0}
    end
    nx = port_abs_num((gx - x))
    ny = port_abs_num((gy - y))
    sx = -(1)
    sy = -(1)
    if (gx > x) then
        sx = 1
    end
    if (gy > y) then
        sy = 1
    end
    ix = 0
    iy = 0
    while ((ix < nx) or (iy < ny)) do
        decision = (((1 + (2 * ix)) * ny) - ((1 + (2 * iy)) * nx))
        if (decision == 0) then
            if ((port_get(data, (((6 + (y * w)) + x) + sx)) ~= 0) or (port_get(data, ((6 + ((y + sy) * w)) + x)) ~= 0)) then
                return {0}
            end
            x = x + sx
            y = y + sy
            ix = ix + 1
            iy = iy + 1
        else
            if (decision < 0) then
                x = x + sx
                ix = ix + 1
            else
                y = y + sy
                iy = iy + 1
            end
        end
        if (port_get(data, ((6 + (y * w)) + x)) ~= 0) then
            return {0}
        end
    end
    return {1}
end
return {compute=compute}
